import {goalCard} from './goals.js';
import {money,shortMoney,dateLabel,metrics,groupTrades,filterTrades,calendarCells} from './data.js';
import {createImportUI} from './imports-ui.js';
import {esc,icon,badge,avatar,empty,button,sparkline,lineChart,barChart,horizontalBars,metricCard} from './ui.js';
import {emptyWorkspace,request,operation,uploadReport} from './cloud.js';
let db=emptyWorkspace(),session=null,authProvider='chatgpt',cloudStatus=null,bootError='';
const applyDB=next=>{const theme=db.theme;db=next;db.theme=theme;};
const today=(timezone=db.profile?.timezone||'UTC')=>{const parts=new Intl.DateTimeFormat('en-US',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(p=>p.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`;};
const anchorDate=()=>today(userSettings().profile?.timezone||'UTC');
const state={role:'user',viewUserId:null,page:'overview',account:'all',range:'month',symbol:'all',session:'all',outcome:'all',query:'',calendarYear:2026,calendarMonth:9,analyticsTab:'Overview',settingsTab:'Profile',tradePage:1,sidebar:false,collapsed:false,journalQuery:'',adminQuery:'',chartMode:'equity'};
const app=document.querySelector('#app'),overlay=document.querySelector('#overlay-root');
let focusBeforeModal=null,toastTimer;
const persist=()=>{try{localStorage.setItem('structure-theme',db.theme);}catch{}};
const hasAdminAccess=()=>session?.role==='admin';
const isAdmin=()=>hasAdminAccess()&&state.role==='admin'&&!state.viewUserId;
const activeUserId=()=>state.viewUserId||session?.id;
const activeUser=()=>db.users.find(u=>u.id===activeUserId());
const userSettings=()=>db.userSettings[activeUserId()]||db;
const userEntries=()=>db.entries.filter(e=>e.userId===activeUserId()&&(db.dataMode!=='real'||!e.demo));
const workspaceHref=page=>state.viewUserId?`#/admin/users/${encodeURIComponent(state.viewUserId)}/${page}`:`#/${state.role}/${page}`;
const canAccessAccount=id=>visibleAccounts().some(a=>a.id===id);
function resetWorkspaceFilters(){Object.assign(state,{account:'all',range:'month',symbol:'all',session:'all',outcome:'all',query:'',journalQuery:'',tradePage:1,analyticsTab:'Overview',settingsTab:'Profile'});}

const visibleAccounts=()=>db.accounts.filter(a=>(isAdmin()||a.userId===activeUserId())&&(db.dataMode!=='real'||!a.demo));
const historyTrades=()=>db.trades.filter(t=>db.dataMode!=='real'||!t.demo);
const rLabel=m=>m.rKnown?m.avgR.toFixed(2)+'R':'—';
const drawdownLabel=m=>m.ddKnown?m.dd.toFixed(2)+'%':'—';
const tradeR=t=>Number.isFinite(t.r)?(t.r>0?'+':'')+t.r.toFixed(2)+'R':'—';
function periodLabel(){const rows=currentTrades();if(!rows.length)return 'No trades in selected period';const dates=rows.map(t=>t.date).sort();return `${dateLabel(dates[0])} – ${dateLabel(dates.at(-1))}`;}
function storageBanner(){return `<div class="journal-local-banner">${icon('shield')}<span>Cloud journal · Changes saved securely across devices</span>${button('Back up data','import-backup','text','download')}</div>`;}
const currentTrades=(extra={})=>filterTrades(db.trades,{...state,anchorDate:anchorDate(),accountIds:visibleAccounts().map(a=>a.id),...extra});
const startBalance=()=>{const accounts=visibleAccounts().filter(a=>state.account==='all'||a.id===state.account);return accounts.some(a=>a.balanceKnown===false)?0:accounts.reduce((s,a)=>s+a.balance,0);};
const currentMetrics=()=>metrics(currentTrades(),startBalance());

const userNav=[['WORKSPACE',[['overview','grid','Overview'],['trades','trades','Trade history'],['calendar','calendar','Trading calendar'],['analytics','chart','Analytics'],['journal','book','Daily journal']]],['MANAGEMENT',[['accounts','wallet','Accounts & licenses'],['imports','download','Import history'],['reports','file','Reports'],['settings','settings','Settings']]]];
const adminNav=[['ADMIN WORKSPACE',[['overview','grid','Platform overview'],['users','users','Users'],['licenses','key','Licenses'],['accounts','wallet','Trading accounts'],['analytics','chart','Platform analytics'],['calendar','calendar','Trading calendar']]],['OPERATIONS',[['imports','download','Import history'],['connections','pulse','Connections'],['activity','clock','Activity log'],['settings','settings','Platform settings']]]];
const importUI=createImportUI({db:()=>db,replaceDB:applyDB,ownerId:activeUserId,platformAdmin:isAdmin,settings:userSettings,render,navigate,modal,close,toast,persist,cloud:true,upload:uploadReport,undo:async id=>{const result=await operation('import.undo',{}, {id});applyDB(result.db);},contextReset:resetWorkspaceFilters,imported:result=>{state.account=result.accountId;state.range='all';state.symbol='all';state.session='all';state.outcome='all';const last=result.batch.dateEnd.split('-');state.calendarYear=Number(last[0]);state.calendarMonth=Number(last[1])-1;}});
function parseRoute(){
 const route=location.hash.slice(1).split('/').filter(Boolean),previousContext=state.role+':'+state.viewUserId;
 if(['login','register','forgot','onboarding'].includes(route[0])){state.page=route[0];state.role='user';state.viewUserId=null;return;}
 state.role=route[0]==='admin'&&hasAdminAccess()?'admin':'user';state.viewUserId=null;
 if(hasAdminAccess()&&route[1]==='users'&&route[2]){
  const user=db.users.find(u=>u.id===route[2]);
  if(user){state.viewUserId=user.id;state.page=route[3]||'overview';}
  else state.page='users';
 }else state.page=route[1]||'overview';
 if(previousContext!==state.role+':'+state.viewUserId){resetWorkspaceFilters();importUI.reset();}
 const valid=(isAdmin()?adminNav:userNav).flatMap(x=>x[1].map(x=>x[0])).concat(['help']);
 if(!valid.includes(state.page))state.page='overview';
 state.sidebar=false;state.query='';state.tradePage=1;
 if(!visibleAccounts().some(a=>a.id===state.account))state.account='all';
}
function navigate(page,role){location.hash=role?`/${role}/${page}`:workspaceHref(page).slice(1);}
function openUserWorkspace(id){
 if(!hasAdminAccess()||!db.users.some(u=>u.id===id))return;
 close();location.hash=`/admin/users/${encodeURIComponent(id)}/overview`;
}
function userWorkspaceBanner(){
 if(!state.viewUserId)return '';
 const user=activeUser();
 return `<section class="admin-view-banner" aria-label="Administrator viewing user workspace"><div class="admin-view-identity"><span class="admin-view-icon">${icon('shield')}</span><div><span class="eyebrow">ADMINISTRATOR · USER WORKSPACE</span><strong>Viewing ${esc(user.name)}’s panel</strong><small>${esc(user.email)} · ${esc(user.status)}</small></div></div><div class="admin-view-actions"><select id="view-user-switch" aria-label="View another user">${selectOptions(db.users.map(u=>[u.id,u.name]),user.id)}</select>${button('User details','user-profile:'+user.id,'secondary','users')}${button('Back to admin','back-to-admin','primary','arrow')}</div></section>`;
}
function toast(message){const el=document.querySelector('#toast-root');el.innerHTML=`<div class="toast">${icon('check')}<span>${esc(message)}</span></div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.innerHTML='',4000);}
function modal(title,body,footer='',wide=false){focusBeforeModal=document.activeElement;overlay.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><span class="eyebrow">STRUCTURE WORKSPACE</span><h2 id="modal-title">${title}</h2></div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-content">${body}</div>${footer?`<footer>${footer}</footer>`:''}</section></div>`;document.body.classList.add('modal-open');setTimeout(()=>overlay.querySelector('input,select,textarea,button')?.focus(),0);}
function close(){overlay.innerHTML='';document.body.classList.remove('modal-open');focusBeforeModal?.focus?.();}
function pageHeading(kicker,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="page-actions">${actions}</div></div>`;}
function panel(title,body,extra='',cls=''){return `<section class="panel ${cls}"><div class="panel-heading"><h3>${title}</h3>${extra}</div>${body}</section>`;}
function selectOptions(values,current){return values.map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('');}
function filters(compact=false){return `<div class="filter-row"><div class="filter-group"><span class="filter-label">${icon('filter')} Filter by</span><select aria-label="Instrument" data-filter="symbol">${selectOptions([['all','All instruments'],...[...new Set(historyTrades().filter(t=>visibleAccounts().some(a=>a.id===t.accountId)).map(t=>t.symbol))].sort().map(x=>[x,x])],state.symbol)}</select><select aria-label="Trading session" data-filter="session">${selectOptions([['all','All sessions'],...['London','New York','Asia','Unclassified'].map(x=>[x,x])],state.session)}</select>${!compact?`<select aria-label="Trade result" data-filter="outcome">${selectOptions([['all','All results'],['win','Winning trades'],['loss','Losing trades']],state.outcome)}</select>`:''}</div>${button('Reset','reset-filters','text','refresh')}</div>`;}
function render(){if(!session){app.innerHTML=authPage();return;}document.documentElement.dataset.theme=db.theme||'light';if(['login','register','forgot','onboarding'].includes(state.page)){app.innerHTML=authPage();return;}
 const nav=isAdmin()?adminNav:userNav,person=isAdmin()?'Administrator':activeUser().name;
 app.innerHTML=`<div class="workspace ${state.collapsed?'is-collapsed':''} ${state.sidebar?'mobile-open':''}"><div class="mobile-scrim" data-action="sidebar"></div><aside class="sidebar"><a class="brand" href="${workspaceHref('overview')}" aria-label="Structure home"><img src="/assets/mark.svg" alt=""/><span>structure<span class="brand-dot">.</span><small>TRADING JOURNAL</small></span></a><div class="workspace-label">${icon(isAdmin()?'shield':'layers')}<span>${isAdmin()?'Admin workspace':state.viewUserId?'User workspace':'Personal workspace'}</span>${icon('down')}</div><nav aria-label="Main navigation">${nav.map(([label,items])=>`<div class="nav-group"><div class="nav-label">${label}</div>${items.map(([id,ic,label])=>`<a title="${label}" class="nav-link ${state.page===id?'active':''}" href="${workspaceHref(id)}">${icon(ic)}<span>${label}</span>${id==='journal'?'<em>'+userEntries().length+'</em>':id==='connections'&&isAdmin()?'<i class="notification-dot"></i>':''}</a>`).join('')}</div>`).join('')}</nav><div class="sidebar-bottom"><div class="insight-promo"><span class="promo-icon">${icon('spark')}</span><strong>Small habits. Real edge.</strong><p>Your next breakthrough starts with a review.</p><a href="${workspaceHref(isAdmin()?'analytics':'journal')}">${isAdmin()?'Explore performance':'Reflect on today'} ${icon('arrow')}</a></div><a href="${workspaceHref('help')}" class="nav-link ${state.page==='help'?'active':''}">${icon('help')}<span>Help & resources</span>${icon('external')}</a><button class="profile-switch" data-action="profile-menu">${avatar(person,isAdmin()?'purple':'gold',true)}<span><strong>${esc(person)}</strong><small>${isAdmin()?'Platform administrator':state.viewUserId?'Viewing as administrator':'Pro workspace'}</small></span>${icon('down')}</button></div><button class="collapse-btn" data-action="collapse" aria-label="Collapse navigation">${icon('chevron')}</button></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" data-action="sidebar" aria-label="Open navigation">${icon('menu')}</button><span>${isAdmin()?'Administration':'Workspace'}</span>${icon('chevron')}<strong>${esc(nav.flatMap(x=>x[1]).find(x=>x[0]===state.page)?.[2]||'Help center')}</strong></div><div class="topbar-actions"><button class="search-shortcut" data-action="search">${icon('search')}<span>Quick search</span><kbd>⌘ K</kbd></button><span class="topbar-divider"></span><button class="demo-pill" data-action="demo-info"><i></i>Cloud journal</button><button class="icon-btn notification-btn" data-action="notifications" aria-label="Notifications">${icon('bell')}<i></i></button>${avatar(person,isAdmin()?'purple':'gold',true)}</div></header><main id="main" tabindex="-1">${userWorkspaceBanner()}${storageBanner()}<div class="workspace-toolbar"><div class="account-select">${icon(isAdmin()?'users':'wallet')}<select aria-label="Select trading account" id="account-filter">${selectOptions([['all',isAdmin()?'All trading accounts':'All accounts'],...visibleAccounts().map(a=>[a.id,a.name])],state.account)}</select><span class="count-pill">${visibleAccounts().length}</span></div><div class="toolbar-right"><span class="sync-status"><i></i>Cloud history</span><div class="date-select">${icon('calendar')}<select id="range-filter" aria-label="Date range">${selectOptions([['month','This month'],['week','This week'],['quarter','Last 3 months'],['all','All time']],state.range)}</select></div><button class="icon-btn" data-action="theme" aria-label="Toggle color theme">${icon('sun')}</button></div></div>${renderPage()}<footer class="page-footer"><span>Made for the trader you’re becoming.</span><span><i class="live-dot"></i> Secure cloud workspace <span class="footer-separator">·</span> Structure © 2026</span></footer></main></div></div>`;
}
function renderPage(){switch(state.page){case'overview':return isAdmin()?adminOverview():overview();case'trades':return tradesPage();case'calendar':return calendarPage();case'analytics':return analyticsPage();case'journal':return journalPage();case'accounts':case'licenses':return accountsPage();case'reports':return reportsPage();case'imports':return importUI.page();case'users':return usersPage();case'connections':return connectionsPage();case'activity':return activityPage();case'settings':return settingsPage();case'help':return helpPage();default:return overview();}}
function personalGoals(){return visibleAccounts().filter(a=>a.goal&&(state.account==='all'||state.account===a.id)&&(state.viewUserId||a.userId===session.id)).map(a=>goalCard(a,historyTrades(),anchorDate())).join('');}
function overview(){const m=currentMetrics(),trades=currentTrades(),daily=groupTrades(trades,'date').sort((a,b)=>a.name.localeCompare(b.name)),recent=[...trades].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).slice(0,5),sessions=groupTrades(trades,'session');return `${pageHeading('YOUR PERFORMANCE, IN PERSPECTIVE','Every trade tells a story<span class="gold-text">.</span>','Your trading history and performance, in one clear workspace.',button('Export report','export','secondary','download')+button('Import MT5 history','import-open','primary','plus'))}${personalGoals()}<div class="overview-meta"><span><i class="live-dot"></i> Performance overview</span><span>${periodLabel()} <span class="muted">· USD</span></span></div><div class="metrics-grid">${metricCard('Net profit & loss',money(m.pnl,true),`<span class="positive-text">${icon('up')} ${startBalance()>0?(m.pnl/startBalance()*100).toFixed(2)+'%':'—'}</span><span>return this period</span>`,'wallet',sparkline(daily.map(x=>x.pnl)),'featured')}${metricCard('Win rate',m.winRate.toFixed(1)+'<small>%</small>',`<span class="positive-text">${m.wins} wins</span><span> / ${m.losses} losses</span>`,'target',`<div class="mini-progress"><i style="width:${m.winRate}%"></i></div>`)}${metricCard('Profit factor',Number.isFinite(m.pf)?m.pf.toFixed(2):'∞',`<span class="positive-text">${icon('check')} ${!m.total?'Awaiting executions':m.pf>=1?'Positive expectancy':'Review performance'}</span>`,'chart',sparkline(daily.map((x,i)=>1.5+(i%3)*.1+x.pnl/2000)))}${metricCard('Total trades',m.total,`<span>${rLabel(m)}</span><span> average return / trade</span>`,'trades',`<div class="mini-blocks">${daily.slice(-14).map(x=>`<i class="${x.pnl>0?'win':'loss'}" style="height:${10+Math.min(Math.abs(x.pnl)/30,24)}px"></i>`).join('')}</div>`)}</div><div class="dashboard-primary">${panel('Performance curve',`<div class="equity-summary"><div><span class="muted">${state.chartMode==='drawdown'?'Maximum drawdown':startBalance()>0?'Closed-trade balance':'Cumulative net P&L'}</span><strong>${state.chartMode==='drawdown'?drawdownLabel(m):money(m.balance)}</strong></div><div class="chart-legend"><i></i>${state.chartMode==='drawdown'?'Drawdown':'Account balance'}</div></div>${state.chartMode==='drawdown'?drawdownChart(m):lineChart(m.curve)}<div class="equity-footer"><span>Starting balance <strong>${money(startBalance())}</strong></span><span>Max drawdown <strong>${drawdownLabel(m)}</strong></span><span>Trading fees <strong>${money(m.fees)}</strong></span></div>`,`<div class="segmented"><button class="${state.chartMode==='equity'?'active':''}" data-action="chart-equity">Equity</button><button class="${state.chartMode==='drawdown'?'active':''}" data-action="chart-drawdown">Drawdown</button></div>`,'equity-panel')}${panel('Your trading edge',`<div class="edge-score"><div class="score-ring" style="--progress:${Math.round(m.winRate)}"><span>${Math.round(m.winRate)}<small>CONSISTENCY</small></span></div><div><span class="badge positive">${m.total?'Building momentum':'Ready for your first trade'}</span><p>Process first.<br>Performance follows.</p></div></div><div class="edge-stats"><div><span>Average win</span><strong>${money(m.avgWin)}</strong></div><div><span>Average loss</span><strong>${money(m.avgLoss)}</strong></div><div><span>Risk / reward</span><strong>1 : ${m.avgLoss?(m.avgWin/m.avgLoss).toFixed(2):'0.00'}</strong></div></div><a class="text-link" href="${workspaceHref('analytics')}">Explore your analytics ${icon('arrow')}</a>`,'<span class="subtle-icon">'+icon('spark')+'</span>','edge-panel')}</div><div class="dashboard-secondary">${panel('Daily performance',barChart(daily.slice(-12).map(x=>({...x,name:new Date(x.name+'T12:00:00').getDate().toString()}))),`<span class="muted small-text">Net P&L · selected period</span>`)}${panel('Performance by session',horizontalBars(sessions),`<a class="text-link" href="${workspaceHref('analytics')}">View all ${icon('arrow')}</a>`)}${panel('A moment to reflect',`<div class="reflection"><div class="reflection-illustration">${icon('book')}<span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><i>✧</i></div><h3>Your EA runs.<br>Your insights grow.</h3><p>What did your automated system reveal today?</p>${button('Write a daily review','new-entry','secondary','edit')}</div>`,'<span class="badge neutral">DAILY JOURNAL</span>','reflection-panel')}</div>${panel('Recent trades',tradeTable(recent),`<a class="text-link" href="${workspaceHref('trades')}">View all trades ${icon('arrow')}</a>`)}<div class="bottom-note">${icon('shield')} Your accounts. Your data. Your edge. <span>Read-only connection — your funds stay with your broker.</span></div>`;}
function drawdownChart(m){if(!m.ddKnown)return empty('Starting balance needed','Percentage drawdown is unavailable without known opening capital. Review the cumulative P&L curve instead.');let peak=m.curve[0]?.value||1;return lineChart(m.curve.map(p=>{peak=Math.max(peak,p.value);return {...p,value:-(peak-p.value)/peak*100};}),{id:'drawdown'});}
function tradeTable(trades,admin=false){if(!trades.length)return empty('No trades in this view','Try another filter or import an MT5 history report.',button('Reset filters','reset-filters','secondary','refresh'));return `<div class="table-scroll"><table><thead><tr><th>Instrument</th><th>Direction</th><th>Date & time</th><th>EA / source</th>${admin?'<th>Account</th>':''}<th>Net P&L</th><th>Return</th><th></th></tr></thead><tbody>${trades.map(t=>`<tr class="clickable" data-action="trade:${t.id}" tabindex="0" aria-label="View ${esc(t.symbol)} trade ${esc(t.ticket)}"><td><div class="instrument"><span class="instrument-mark ${t.symbol==='XAUUSD'?'gold':t.symbol==='BTCUSD'?'orange':'blue'}">${t.symbol==='XAUUSD'?'Au':t.symbol==='BTCUSD'?'₿':esc(t.symbol.slice(0,2))}</span><span><strong>${esc(t.symbol)}</strong><small>${Number(t.lots).toFixed(2)} lots <span>· ${t.source}</span></small></span></div></td><td>${badge(t.side)}</td><td><span>${dateLabel(t.date).replace(', 2026','')}</span><small class="block muted">${t.time} · ${esc(t.session)}</small></td><td><span class="setup-tag">${esc(t.eaName)}</span></td>${admin?`<td>${esc(db.accounts.find(a=>a.id===t.accountId)?.name)}</td>`:''}<td class="number ${t.pnl-t.fees>=0?'positive-text':'negative-text'}">${money(t.pnl-t.fees,true)}</td><td><span class="r-value ${t.r==null?'muted':t.r>0?'positive-text':'negative-text'}">${tradeR(t)}</span></td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table></div>`;}
function tradesPage(){const trades=[...currentTrades()].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)),m=metrics(trades),size=12,pages=Math.max(1,Math.ceil(trades.length/size));state.tradePage=Math.min(state.tradePage,pages);return `${pageHeading('THE DETAILS MAKE THE DIFFERENCE','Your trade history','EA executions and imported MT5 reports, together in your journal.',button('Export CSV','export','secondary','download')+button('Import MT5 history','import-open','primary','plus'))}${filters()}<div class="inline-summary"><span><strong>${m.total}</strong> trades</span><span>Net P&L <strong class="${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)}</strong></span><span>Win rate <strong>${m.winRate.toFixed(1)}%</strong></span><div class="table-search">${icon('search')}<input id="trade-search" aria-label="Search trades" placeholder="Search instrument, EA, ticket…" value="${esc(state.query)}"></div></div>${panel('All trades',tradeTable(trades.slice((state.tradePage-1)*size,state.tradePage*size))+`<div class="pagination"><span>Showing ${trades.length?(state.tradePage-1)*size+1:0}–${Math.min(state.tradePage*size,trades.length)} of ${trades.length} trades</span><div><button class="btn secondary" data-action="prev-trades" ${state.tradePage===1?'disabled':''}>Previous</button><span>${state.tradePage} / ${pages}</span><button class="btn secondary" data-action="next-trades" ${state.tradePage>=pages?'disabled':''}>Next</button></div></div>`,badge(db.dataMode==='real'?'MT5 history':'EA sync only','neutral'))}`;}
function calendarPage(){const all=currentTrades({range:'all'}),cells=calendarCells(state.calendarYear,state.calendarMonth),monthKey=`${state.calendarYear}-${String(state.calendarMonth+1).padStart(2,'0')}`,monthTrades=all.filter(t=>t.date.startsWith(monthKey)),m=metrics(monthTrades),groups=Object.fromEntries(groupTrades(all,'date').map(x=>[x.name,x])),monthName=new Date(state.calendarYear,state.calendarMonth,1).toLocaleDateString('en-US',{month:'long',year:'numeric'}),winDays=Object.values(groups).filter(x=>x.name.startsWith(monthKey)&&x.pnl>0).length,lossDays=Object.values(groups).filter(x=>x.name.startsWith(monthKey)&&x.pnl<0).length;return `${pageHeading('SEE THE BIGGER PICTURE','Trading calendar','Your progress, one trading day at a time.',(isAdmin()?button('Export trades','export','primary','download'):button('Daily review','new-entry','primary','edit')))}<div class="calendar-summary">${metricCard('Monthly net P&L',money(m.pnl,true),`${m.total} trades this month`,'wallet')}${metricCard('Profitable days',winDays,`<span class="positive-text">${icon('up')} Consistency over intensity</span>`,'calendar')}${metricCard('Losing days',lossDays,'Every loss holds a lesson','shield')}${metricCard('Best day',money(Math.max(0,...Object.values(groups).filter(x=>x.name.startsWith(monthKey)).map(x=>x.pnl)),true),'Your strongest performance','flag')}</div><section class="panel calendar-panel"><div class="panel-heading"><div class="flex gap"><h3>${monthName}</h3><span class="badge neutral">${m.total} trades</span></div><div class="flex gap"><span class="calendar-legend"><i class="positive-dot"></i>Profit <i class="negative-dot"></i>Loss</span><button class="btn secondary compact" data-action="calendar-today">This month</button><button class="icon-btn bordered" data-action="calendar-prev" aria-label="Previous month">${icon('chevron','rotate')}</button><button class="icon-btn bordered" data-action="calendar-next" aria-label="Next month">${icon('chevron')}</button></div></div><div class="calendar-weekdays">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.map(c=>{const g=groups[c.date];return `<button class="calendar-cell ${!c.current?'outside':''} ${g?(g.pnl>0?'profit-day':'loss-day'):''} ${c.date===anchorDate()?'today':''}" data-action="day:${c.date}" aria-label="${dateLabel(c.date)}, ${g?money(g.pnl,true)+', '+g.total+' trades':'no trades'}"><span class="day-number">${c.day}${c.date===anchorDate()?'<small>TODAY</small>':''}</span>${g?`<strong>${money(g.pnl,true)}</strong><span class="day-trades">${g.total} trades <i>·</i> ${g.winRate.toFixed(0)}% win</span><div class="day-dots">${g.trades.slice(0,8).map(t=>`<i class="${t.pnl-t.fees>0?'win':'loss'}"></i>`).join('')}</div>`:'<span class="no-trades">—</span>'}</button>`;}).join('')}</div><div class="calendar-bottom"><span>${icon('eye')} Select a day to review trades and write a reflection.</span><strong class="${m.pnl>=0?'positive-text':'negative-text'}">Monthly return ${money(m.pnl,true)}</strong></div></section>`;}
function analyticsPage(){const trades=currentTrades(),m=metrics(trades,startBalance()),tab=state.analyticsTab,groups=groupTrades(trades,tab==='Instruments'?'symbol':tab==='Expert Advisors'?'eaName':tab==='Weekdays'?t=>new Date(t.date+'T12:00:00').toLocaleDateString('en-US',{weekday:'long'}):'session');return `${pageHeading('UNDERSTAND YOUR EDGE',isAdmin()?'Platform analytics':'Beyond the P&L','Find the patterns that make you a more consistent trader.',button('Export analysis','export','secondary','download'))}${filters(true)}<div class="tabs">${['Overview','Sessions','Instruments','Expert Advisors','Weekdays','Risk analysis'].map(x=>`<button class="${x===tab?'active':''}" data-action="analytics:${x}">${x}</button>`).join('')}</div><div class="metrics-grid">${metricCard('Expectancy',money(m.total?m.pnl/m.total:0,true),'Average net result per trade','target')}${metricCard('Average return',rLabel(m),'Realized reward / initial risk','chart')}${metricCard('Max drawdown',drawdownLabel(m),'Peak to trough in selected period','shield')}${metricCard('Average hold',Math.round(trades.reduce((s,t)=>s+t.duration,0)/(trades.length||1))+'<small>min</small>','Time in the market','clock')}</div>${tab==='Risk analysis'?`<div class="two-col">${panel('Execution outcomes',horizontalBars(groupTrades(trades,t=>t.pnl-t.fees>0?'Winning trades':'Losing trades')))}${panel('Your risk guardrails',`<div class="guardrails"><div>${icon('shield')}<span>Risk per trade</span><strong>${userSettings().risk.perTrade}%</strong></div><div>${icon('flag')}<span>Daily loss limit</span><strong>${userSettings().risk.dailyLoss}%</strong></div><div>${icon('trades')}<span>Maximum trades / day</span><strong>${userSettings().risk.maxTrades}</strong></div><p class="info-note">Guardrails help guide your reviews. In this UI demo they do not control your EA or broker account.</p>${button('Edit risk plan','risk-settings','secondary','edit')}</div>`)}${panel('Automated execution review',`<div class="insight-content">${icon('heart')}<h3>Monitor the system. Review the results.</h3><p>Compare your EAs by net return, drawdown, holding time, and execution volume. Use daily reviews to record system observations.</p><a href="${workspaceHref('journal')}" class="text-link">Open daily journal ${icon('arrow')}</a></div>`)}</div>`:`<div class="two-col">${panel(tab==='Overview'?'Equity progression':`Net return by ${tab.toLowerCase()}`,tab==='Overview'?lineChart(m.curve):barChart(groups))}${panel(tab==='Overview'?'Your best trading sessions':`${tab} breakdown`,horizontalBars(groups))}</div>${panel('Performance breakdown',`<div class="table-scroll"><table><thead><tr><th>${tab==='Overview'?'Session':tab}</th><th>Trades</th><th>Win rate</th><th>Profit factor</th><th>Average R</th><th>Net P&L</th></tr></thead><tbody>${groups.map(g=>`<tr><td><strong>${esc(g.name)}</strong></td><td>${g.total}</td><td>${g.winRate.toFixed(1)}%</td><td>${Number.isFinite(g.pf)?g.pf.toFixed(2):'∞'}</td><td>${rLabel(g)}</td><td class="number ${g.pnl>=0?'positive-text':'negative-text'}">${money(g.pnl,true)}</td></tr>`).join('')}</tbody></table></div>`)}<div class="insight-banner">${icon('spark')}<div><strong>Let the data shape your process.</strong><p>${groups.length?`${esc([...groups].sort((a,b)=>b.pnl-a.pnl)[0].name)} leads your selected period. Review the EA executions behind those results before changing your configuration.`:'Connect an MT5 account to reveal your EA performance patterns.'}</p></div></div>`}`;}
function journalPage(){const entries=userEntries().filter(e=>(e.title+' '+e.content).toLowerCase().includes(state.journalQuery.toLowerCase()));return `${pageHeading('THE PART THE CHART DOESN’T SHOW','Your daily journal','Build self-awareness. Protect your mindset. Sharpen your process.',button('New reflection','new-entry','primary','plus'))}<div class="journal-layout"><div><div class="journal-intro"><div>${icon('book')}<span>One honest review is worth more than ten new indicators.</span></div><div class="table-search">${icon('search')}<input id="journal-search" value="${esc(state.journalQuery)}" placeholder="Search your reflections" aria-label="Search journal"></div></div>${entries.length?entries.map(e=>`<article class="journal-entry"><div class="entry-date"><strong>${new Date(e.date+'T12:00:00').getDate()}</strong><small>${new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{month:'short'}).toUpperCase()}</small></div><div class="entry-body"><div class="flex between"><span class="muted small-text">${dateLabel(e.date)} · Daily reflection</span><button class="icon-btn" data-action="edit-entry:${e.id}" aria-label="Edit reflection">${icon('edit')}</button></div><h2>${esc(e.title)}</h2><p>${esc(e.content).replace(/\n/g,'<br>')}</p><div class="flex gap">${badge(e.mood)}<span class="entry-rating">${'★'.repeat(e.rating)}<span>${'★'.repeat(5-e.rating)}</span></span><small class="muted">Process rating</small></div></div></article>`).join(''):empty('A fresh page','Write your first reflection to start building your trading story.',button('Write reflection','new-entry','primary','edit'))}</div><aside>${panel('Your review ritual',`<ol class="ritual"><li><span>01</span><div><strong>Before the session</strong><p>How do I feel? What is my plan?</p></div></li><li><span>02</span><div><strong>After each trade</strong><p>Did I follow the rules I set?</p></div></li><li><span>03</span><div><strong>At the end of the day</strong><p>What will I do better tomorrow?</p></div></li></ol>`)}<blockquote>“The goal of a successful trader is to make the best trades. Money is secondary.”<cite>— Alexander Elder</cite></blockquote></aside></div>`;}
function accountsPage(){const accounts=visibleAccounts().filter(a=>state.page!=='licenses'||a.mode!=='import');return `${pageHeading(isAdmin()?'LICENSE & ACCOUNT MANAGEMENT':'ONE LICENSE. ONE TRADING ACCOUNT.',state.page==='licenses'?'License management':isAdmin()?'Trading accounts':'Accounts & licenses',isAdmin()?'Manage ownership, license access, and MT5 connection health.':'Your trading world, connected. Keep every account in one workspace.',isAdmin()?button('Issue license','issue-license','primary','plus'):button('Activate license','activate-license','primary','key'))}${personalGoals()}<div class="account-totals"><span>${icon('wallet')} <strong>${accounts.length}</strong> total accounts</span><span><i class="live-dot"></i><strong>${accounts.filter(a=>a.connection==='Connected').length}</strong> connected</span><span>${icon('key')}<strong>${accounts.filter(a=>a.status==='Active'&&a.mode!=='import').length}</strong> active licenses</span><span>${icon('shield')} Read-only MT5 sync</span></div><div class="account-grid">${accounts.map(a=>{const user=db.users.find(u=>u.id===a.userId),m=metrics(historyTrades().filter(t=>t.accountId===a.id),a.balance);return `<article class="panel account-card"><div class="account-card-top"><span class="broker-mark">${a.broker==='Not connected'?icon('plus'):a.broker.slice(0,2)}</span><div>${badge(a.connection)} <span class="account-type">${a.type}</span></div></div><h2>${esc(a.name)}</h2><p>${esc(a.broker)} ${a.number?'· #'+esc(a.number):'· Ready to connect'}${isAdmin()?`<br><small>Owned by ${esc(user?.name||'Unknown user')}</small>`:''}</p><div class="account-balance"><span>${a.mode==='import'?(a.balanceKnown===false?'Cumulative net P&L':'Closed-trade balance'):'Account equity'}</span><strong>${money(m.balance)}</strong><span class="${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)} <span class="muted">all time</span></span></div><div class="license-line"><span>${icon('key')}<code>${esc(a.license)}</code></span><button class="icon-btn" data-action="copy:${a.license}" aria-label="Copy license">${icon('copy')}</button></div><div class="account-detail-row"><span>License status</span>${badge(a.status)}</div><div class="account-detail-row"><span>Valid until</span><strong>${a.expiry?dateLabel(a.expiry):'Not applicable'}</strong></div><div class="account-detail-row"><span>${a.mode==='import'?'Last import':'Last sync'}</span><strong>${a.lastImportedAt?dateLabel(a.lastImportedAt.slice(0,10)):a.lastSync?dateLabel(a.lastSync.slice(0,10)):'Awaiting connection'}</strong></div><div class="account-card-actions">${a.mode==='import'?button('Import more history','import-open','primary','download'):a.status==='Active'?button(a.connection==='Connected'?'Connection details':'Connect MT5','connect:'+a.id,a.connection==='Connected'?'secondary':'primary','link'):button('License details','account:'+a.id,'secondary','key')}<button class="icon-btn bordered" data-action="account:${a.id}" aria-label="Manage ${esc(a.name)}">${icon('settings')}</button></div></article>`;}).join('')}</div><div class="connection-guide"><div class="guide-title">${icon('link')}<h3>From your terminal to your journal.</h3><p>Four simple steps. One connected workspace.</p></div>${[['01','Activate a license','Each license creates one journal account.'],['02','Connect your MT5','Bind the license to one account number.'],['03','Install the connector','Add the Structure bridge EA to your terminal.'],['04','Review your edge','Trades and performance appear in your journal.']].map(([n,t,d])=>`<div class="guide-step"><span>${n}</span><strong>${t}</strong><p>${d}</p></div>`).join('')}</div><p class="prototype-note">${icon('shield')} Account bindings and credentials are checked by the server. Connected status requires a real terminal heartbeat.</p>`;}
function reportsPage(){const m=currentMetrics();return `${pageHeading('PROGRESS WORTH REVIEWING','Reports & exports','A clear view of your performance, ready to take with you.',button('Export trades','export','secondary','download')+button('Import MT5 history','import-open','primary','plus'))}<div class="report-feature"><div><span class="eyebrow">${state.range.toUpperCase()} · PERFORMANCE REVIEW</span><h2>A history of decisions.<br>A clearer picture of your edge.</h2><p>Your performance summary across the selected accounts.</p><div class="flex gap">${button('Open monthly report','monthly-report','primary','file')}${button('Download CSV','export','secondary','download')}</div></div><div class="report-preview"><div class="report-preview-top"><img src="/assets/mark.svg" alt="Structure mark"/><span>PERFORMANCE REPORT</span></div><span class="muted">Net performance</span><strong class="positive-text">${money(m.pnl,true)}</strong>${sparkline(m.curve.map(x=>x.value),'gold',true)}<div><span>Win rate <b>${m.winRate.toFixed(1)}%</b></span><span>Trades <b>${m.total}</b></span></div></div></div><div class="three-col">${[['Trade ledger','Every fill, fee, and realized result.','trades','export'],['Performance summary','A focused overview of your key metrics.','chart','summary-export'],['Daily breakdown','Daily results for your own analysis.','calendar','daily-export']].map(([t,d,ic,a])=>panel(t,`<div class="report-option">${icon(ic)}<p>${d}</p>${button('Download CSV',a,'secondary','download')}</div>`,badge('CSV','neutral'))).join('')}</div>`;}
function adminOverview(){const trades=currentTrades(),m=currentMetrics(),users=db.users,accountIds=visibleAccounts().map(a=>a.id),rank=users.map(u=>({...u,...metrics(trades.filter(t=>db.accounts.find(a=>a.id===t.accountId)?.userId===u.id))})).sort((a,b)=>b.pnl-a.pnl);return `${pageHeading('YOUR PLATFORM AT A GLANCE','A clear view of everyone<span class="gold-text">.</span>','Manage your traders, monitor account health, and see the bigger picture.',button('Issue license','issue-license','secondary','key')+button('Add user','add-user','primary','plus'))}${personalGoals()}<div class="metrics-grid">${metricCard('Platform net P&L',money(m.pnl,true),`${m.total} trades across the platform`,'chart',sparkline(m.curve.map(x=>x.value)),'featured')}${metricCard('Total users',users.length,`${users.filter(x=>x.status==='Active').length} active · ${users.filter(x=>x.status==='Invited').length} invited`,'users')}${metricCard('Active licenses',visibleAccounts().filter(a=>a.status==='Active'&&a.mode!=='import').length,`${visibleAccounts().filter(a=>a.mode!=='import').length} licenses issued`,'key')}${metricCard('Connected accounts',visibleAccounts().filter(a=>a.connection==='Connected').length,`<span class="negative-text">${visibleAccounts().filter(a=>['Disconnected','Offline'].includes(a.connection)).length} need attention</span>`,'link')}</div><div class="dashboard-primary">${panel('Platform performance',lineChart(m.curve),badge('All selected accounts','neutral'))}${panel('Connection health',`<div class="health-ring">${icon('pulse')}<strong>${visibleAccounts().filter(a=>a.connection==='Connected').length}<small>CONNECTED</small></strong></div><div class="edge-stats"><div><span>Connected</span><strong class="positive-text">${visibleAccounts().filter(a=>a.connection==='Connected').length}</strong></div><div><span>Offline</span><strong class="negative-text">${visibleAccounts().filter(a=>['Disconnected','Offline'].includes(a.connection)).length}</strong></div><div><span>Pending activation</span><strong>${visibleAccounts().filter(a=>!a.number).length}</strong></div></div><a class="text-link" href="#/admin/connections">Monitor connections ${icon('arrow')}</a>`)}</div><div class="two-col">${panel('Trader performance',`<div class="leaderboard">${rank.map((u,i)=>`<button data-action="user:${u.id}"><span class="rank">${String(i+1).padStart(2,'0')}</span>${avatar(u.name,u.color,true)}<span class="leader-name"><strong>${esc(u.name)}</strong><small>${u.total} trades · ${u.winRate.toFixed(0)}% win rate</small></span><strong class="${u.pnl>=0?'positive-text':'negative-text'}">${money(u.pnl,true)}</strong>${icon('chevron')}</button>`).join('')}</div>`,`<a href="#/admin/users" class="text-link">All users ${icon('arrow')}</a>`)}${panel('Recent activity',activityList(db.activity.slice(0,5)),`<a href="#/admin/activity" class="text-link">View log ${icon('arrow')}</a>`)}</div>`;}
function usersPage(){const users=db.users.filter(u=>(u.name+' '+u.email+' '+u.status).toLowerCase().includes(state.adminQuery.toLowerCase()));return `${pageHeading('PEOPLE BEHIND THE PERFORMANCE','User management','Invite traders, review performance, and manage account access.',button('Add user','add-user','primary','plus'))}<div class="inline-summary"><span><strong>${db.users.length}</strong> users</span><span><i class="live-dot"></i> ${db.users.filter(x=>x.status==='Active').length} active</span><div class="table-search">${icon('search')}<input id="admin-search" value="${esc(state.adminQuery)}" placeholder="Search users…" aria-label="Search users"></div></div>${panel('All users',users.length?`<div class="table-scroll"><table><thead><tr><th>User</th><th>Status</th><th>Licenses</th><th>Net P&L</th><th>Win rate</th><th>Joined</th><th></th></tr></thead><tbody>${users.map(u=>{const accounts=visibleAccounts().filter(a=>a.userId===u.id),m=metrics(historyTrades().filter(t=>accounts.some(a=>a.id===t.accountId)));return `<tr class="clickable" tabindex="0" data-action="user:${u.id}"><td><div class="instrument">${avatar(u.name,u.color,true)}<span><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></span></div></td><td>${badge(u.status)}</td><td>${accounts.filter(a=>a.mode!=='import').length} licenses</td><td class="number ${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)}</td><td>${m.winRate.toFixed(1)}%</td><td>${dateLabel(u.joined)}</td><td>${icon('chevron')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No matching users','Try another name, email, or status.'))}`;}
function connectionsPage(){return `${pageHeading('KEEP YOUR DATA FLOWING','Connection monitor','Track MT5 heartbeats, sync status, and accounts that need attention.',button('Refresh status','refresh-connections','secondary','refresh'))}<div class="status-banner">${icon('shield')}<div><strong>Read-only journal sync service</strong><p>These are real account statuses. Keep the MT5 bridge running to receive heartbeats and closed-trade history.</p></div>${badge('Cloud','neutral')}</div>${panel('MT5 connections',`<div class="table-scroll"><table><thead><tr><th>Account</th><th>Owner</th><th>Server</th><th>Status</th><th>Last heartbeat</th><th></th></tr></thead><tbody>${db.accounts.map(a=>`<tr><td><strong>${esc(a.name)}</strong><small class="block muted">${a.number?'#'+a.number:'Unbound license'}</small></td><td>${esc(db.users.find(u=>u.id===a.userId)?.name)}</td><td>${esc(a.server||'—')}</td><td>${badge(a.connection)}</td><td>${a.lastSync?esc(a.lastSync.replace('T',' ')):'Awaiting setup'}</td><td>${button('Inspect',(a.mode==='import'?'account:':'connect:')+a.id,'secondary compact','eye')}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Sync event stream',activityList(db.activity.filter(x=>x.type==='sync')),badge('Server events','neutral'))}`;}
function activityList(items){return items.length?`<div class="activity-list">${items.map(e=>`<div><span class="activity-icon">${icon(e.type==='sync'?'refresh':e.type==='license'?'key':e.type==='user'?'users':'clock')}</span><span><strong>${esc(e.text)}</strong><small>${esc(e.time)}</small></span><i class="live-dot"></i></div>`).join('')}</div>`:empty('No events yet','Workspace changes will appear here.');}
function activityPage(){return `${pageHeading('A TRANSPARENT WORKSPACE','Activity log','License changes, user actions, and connection events.',button('Export log','activity-export','secondary','download'))}${panel('Workspace activity',activityList(db.activity),badge(db.activity.length+' events','neutral'))}`;}
function cloudflarePanel(){const c=cloudStatus||{};return `${pageHeading('CLOUDFLARE INTEGRATION','Your journal, in your cloud.','Connect your Cloudflare KV namespace. Credentials stay encrypted on the server.',button('Back to settings','settings:Profile','secondary','arrow'))}<div class="settings-layout"><section class="panel settings-panel"><div class="panel-heading"><h3>Workers KV</h3>${badge(c.connected?'Connected':'Not connected',c.connected?'positive':'neutral')}</div><p class="muted">D1 protects users, permissions, and transactional trade records. KV keeps versioned journal snapshots in your Cloudflare account.</p>${c.connected?`<div class="detail-grid"><div><small>Account ID</small><strong>${esc(c.accountId||'Worker binding')}</strong></div><div><small>Namespace ID</small><strong>${esc(c.namespaceId||'JOURNAL_KV')}</strong></div><div><small>Last completed sync</small><strong>${esc(c.lastSync||'Awaiting first sync')}</strong></div><div><small>Pending changes</small><strong>${c.pending||0}</strong></div></div><div class="form-footer">${button('Retry pending sync','cloud-sync','primary','refresh')}${c.mode==='api'?button('Disconnect KV','cloud-disconnect','secondary'):''}</div><p class="info-note">Disconnecting stops future snapshots. Existing KV snapshots and your cloud journal remain available.</p>`:`<form id="cloudflare-form"><label>Cloudflare account ID<input name="accountId" pattern="[a-fA-F0-9]{32}" required maxlength="32" autocomplete="off" placeholder="32-character account ID"></label><label>KV namespace ID<input name="namespaceId" pattern="[a-fA-F0-9]{32}" required maxlength="32" autocomplete="off" placeholder="32-character namespace ID"></label><label>Scoped Cloudflare API token<input name="token" type="password" required minlength="20" maxlength="256" autocomplete="off" placeholder="Workers KV Storage · Edit"></label><p class="info-note">Use an API token scoped to Workers KV Storage Edit for this account. A short-lived test value verifies write access. The token is never returned to the browser.</p><div class="form-footer"><button class="btn primary" type="submit">Connect Cloudflare ${icon('link')}</button></div></form>`}</section><aside class="settings-aside">${icon('shield')}<h3>Connect in three steps.</h3><ol class="number-list"><li>In Cloudflare, create a Workers KV namespace for Structure.</li><li>Create an API token with Workers KV Storage Edit permission for your account.</li><li>Enter the account ID, namespace ID, and scoped token here.</li></ol><p>Your token belongs here, never in chat or source code.</p><a href="https://developers.cloudflare.com/kv/get-started/" target="_blank" rel="noopener noreferrer" class="text-link">Cloudflare KV setup ${icon('external')}</a></aside></div>`;}
function settingsPage(){const tab=state.settingsTab,admin=isAdmin();if(tab==='Cloudflare'&&hasAdminAccess())return cloudflarePanel();return `${pageHeading('MAKE IT YOUR WORKSPACE',admin?'Platform settings':'Settings','Your profile, review preferences, and secure access.')}<div class="tabs">${['Profile','Preferences','Risk management','Notifications','Security',...(hasAdminAccess()?['Cloudflare']:[])].map(x=>`<button class="${x===tab?'active':''}" data-action="settings:${x}">${x}</button>`).join('')}</div><div class="settings-layout"><section class="panel settings-panel">${tab==='Profile'?`<form id="profile-form"><h3>Personal information</h3><div class="profile-photo">${avatar(userSettings().profile.name)}<div><strong>${esc(userSettings().profile.name)}</strong><small>${admin?'Administrator':'Workspace owner'}</small></div></div><div class="form-grid"><label>Full name<input name="name" value="${esc(userSettings().profile.name)}" required maxlength="70"></label><label>Verified email<input name="email" value="${esc(userSettings().profile.email)}" readonly></label><label>Timezone<select name="timezone">${selectOptions(['Asia/Karachi','Europe/London','America/New_York','UTC'].map(x=>[x,x]),userSettings().profile.timezone)}</select></label><label>Reporting currency<select name="currency"><option>USD</option></select></label></div><p class="info-note">Your sign-in provider manages your email. Imported timestamps keep their broker timezone; choose its UTC offset during import.</p><div class="form-footer"><button class="btn primary" type="submit">Save profile ${icon('check')}</button></div></form>`:tab==='Risk management'?`<form id="risk-form"><h3>Your review thresholds</h3><label>Risk per trade (%)<input name="perTrade" type="number" min="0.1" max="100" step="0.1" value="${userSettings().risk.perTrade}" required></label><label>Daily loss limit (%)<input name="dailyLoss" type="number" min="0.1" max="100" step="0.1" value="${userSettings().risk.dailyLoss}" required></label><label>Maximum trades per day<input name="maxTrades" type="number" min="1" max="100" value="${userSettings().risk.maxTrades}" required></label><p class="info-note">Review thresholds do not control your EA or place trades.</p><div class="form-footer"><button class="btn primary" type="submit">Save thresholds</button></div></form>`:tab==='Notifications'?`<form id="preferences-form"><h3>Review preferences</h3>${[['email','Email notifications','Save your preference for future notification delivery.'],['sync','Connection alerts','Show connection attention indicators.'],['weekly','Weekly review','Save your weekly review preference.']].map(([k,t,d])=>`<label class="toggle-row"><span><strong>${t}</strong><small>${d}</small></span><input type="checkbox" name="${k}" ${userSettings().preferences[k]?'checked':''}><i class="toggle"></i></label>`).join('')}<p class="info-note">Preferences sync across devices. Email delivery is not configured.</p><div class="form-footer"><button class="btn primary" type="submit">Save preferences</button></div></form>`:tab==='Security'?`<h3>Security & access</h3><div class="security-row">${icon('shield')}<div><strong>Verified sign-in</strong><small>Use password sign-in for the configured owner, or verified ChatGPT sign-in. Plaintext passwords are never stored.</small></div>${badge('Protected')}</div><div class="security-row">${icon('users')}<div><strong>Workspace access</strong><small>${session.role==='admin'?'Administrator · Full platform access':'User · Your accounts and journal'}</small></div>${badge('Active')}</div><div class="security-row">${icon('key')}<div><strong>EA connector credentials</strong><small>Each account has a separate, revocable connector credential.</small></div><a class="text-link" href="${workspaceHref('accounts')}">Manage accounts</a></div><div class="form-footer">${button('Sign out','signout','secondary','logout')}</div>`:`<h3>Workspace preferences</h3><div class="toggle-row"><span><strong>Color appearance</strong><small>Saved on this device.</small></span>${button(db.theme==='dark'?'Use light theme':'Use dark theme','theme','secondary','sun')}</div><div class="toggle-row"><span><strong>Journal backup</strong><small>Download your permitted account history and reviews.</small></span>${button('Download backup','import-backup','secondary','download')}</div>`}</section><aside class="settings-aside">${icon('shield')}<h3>Your workspace, protected.</h3><p>Permissions are checked by the server on every request. Your trade history and reviews are saved to the cloud.</p>${hasAdminAccess()?button('Connect Cloudflare KV','settings:Cloudflare','secondary','link'):''}</aside></div>`;}
function helpPage(){return `${pageHeading('A LITTLE GUIDANCE GOES A LONG WAY','Help & resources','From your MT5 terminal to a secure cloud journal.')}<div class="three-col">${[['Import MT5 history','Upload exported HTML, XML, XLSX, or CSV history.','download','import-open'],['Connect your EA','Bind an account and configure the read-only bridge.','link','help-connect'],['Export your data','Download the selected trades as a CSV.','download','export']].map(([t,d,ic,a])=>panel(t,`<div class="report-option">${icon(ic)}<p>${d}</p>${button('Get started',a,'secondary','arrow')}</div>`)).join('')}</div>${panel('Frequently asked questions',`<div class="faq">${[['How do accounts and licenses work?','Each administrator-issued license represents one account, bound to one MT5 login and broker server. Imported file accounts can be created without an EA license.'],['Can I add trades myself?','Upload an MT5 history export. There is no individual trade-entry form. Execution fields stay read-only; you can add review notes.'],['Can an administrator open any user panel?','Yes. Administrators can open the full panel from Users, including all accounts, trades, reviews, calendar, and settings. The server checks the administrator role.'],['How does sign-in work?','The configured administrator can sign in with email and password. Other traders can use verified ChatGPT sign-in. Your server-side identity determines your workspace. An administrator can pre-add a trader using the exact email they use to sign in.'],['Where is my data stored?','Transactional journal records and permissions use Cloudflare D1. Administrators can connect their own Workers KV namespace for versioned journal snapshots. Browser storage only keeps your color preference.'],['Will the bridge place trades?','No. The provided bridge only reads completed EA positions and sends history over HTTPS. It does not use trading functions or ask for your broker password.'],['How do I connect Cloudflare?','Administrators can use Settings → Cloudflare to enter a scoped Workers KV API token and namespace IDs. Never share API tokens in chat.']].map(([q,a])=>`<details><summary>${q}${icon('plus')}</summary><p>${a}</p></details>`).join('')}</div>`)}`;}
function authPage(){return `<div class="auth-layout"><section class="auth-story"><a class="brand" href="/"><img src="/assets/mark.svg" alt=""><span>structure<span class="brand-dot">.</span><small>TRADING JOURNAL</small></span></a><div class="auth-story-main"><span class="eyebrow">YOUR PROCESS. YOUR PROGRESS.</span><h1>Every account.<br>One clear<br><em>perspective.</em></h1><p>Your automated trading history.<br>Your process, made visible.</p><div class="auth-art">${sparkline([2,3,2.5,5,4,6,5,7,6,9,8,11,10,14,13,16],'gold',true)}<span>${icon('chart')} Your edge, made visible.</span></div></div><small>Secure accounts. Thoughtful insights.</small></section><section class="auth-form-area"><div class="auth-form"><div class="auth-mark">${icon('shield')}</div><span class="eyebrow">WELCOME TO STRUCTURE</span><h2>Your journal.<br>Ready when you are.</h2><p>Sign in securely to access your accounts, trade history, and daily reviews.</p>${bootError?`<div class="import-error" role="alert">${esc(bootError)}</div>`:''}<form id="password-login-form"><label>Email address<input type="email" name="email" autocomplete="username" required placeholder="you@example.com"></label><label>Password<input type="password" name="password" autocomplete="current-password" required maxlength="256" placeholder="Enter your password"></label><button class="btn primary full" type="submit">Sign in ${icon('arrow')}</button></form><div class="auth-divider"><span>or use your verified identity</span></div><a class="btn secondary full" href="/signin-with-chatgpt?return_to=%2F" target="_top">Continue with ChatGPT ${icon('arrow')}</a><div class="auth-divider"><span>One secure identity</span></div><div class="onboarding-steps"><div>${icon('shield')}<span>Verified user and administrator access</span></div><div>${icon('wallet')}<span>Every MT5 account in one workspace</span></div><div>${icon('calendar')}<span>History, calendar, and analytics</span></div></div><p class="auth-alt">Already added by your administrator? Sign in with the same email address.</p><div class="auth-demo-note">${icon('lock')} Password sign-in uses a secure, revocable session.</div>${bootError?button('Retry connection','retry-boot','secondary full','refresh'):''}</div><small class="auth-copyright">© 2026 Structure. Every trade is a lesson.</small></section></div>`;}
function showTrade(id){const t=db.trades.find(t=>t.id===id);if(!t||!canAccessAccount(t.accountId))return;const a=db.accounts.find(a=>a.id===t.accountId);modal(`${esc(t.symbol)} <span class="muted">#${esc(t.ticket)}</span>`,`<div class="trade-detail-top"><div>${badge(t.side)} ${badge(t.source,'neutral')}</div><strong class="${t.pnl-t.fees>=0?'positive-text':'negative-text'}">${money(t.pnl-t.fees,true)}<small>Net profit & loss</small></strong></div><div class="trade-price-art"><span>ENTRY <strong>${t.entry==null?'—':t.entry.toFixed(t.entry<10?5:2)}</strong></span><div>${icon('arrow')}<span>${tradeR(t)}</span></div><span>EXIT <strong>${t.exit==null?'—':t.exit.toFixed(t.exit<10?5:2)}</strong></span></div><div class="detail-grid">${[['Expert Advisor',t.eaName],['Magic number',t.magic??'Not provided'],['Account',a?.name],['Date',dateLabel(t.date)],['Time / session',`${t.time} · ${t.session}`],['Position size',t.lots+' lots'],['Holding time',t.duration==null?'Not provided':Math.round(t.duration)+' minutes'],['Trading costs & swap',money(t.fees)]].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div><form id="trade-review-form" data-id="${id}"><div class="info-note">${icon('shield')} Synced execution data is read-only. Your review notes do not change MT5 trade history.</div><label>Setup quality<select name="grade">${selectOptions([['','Not graded'],['A+','A+'],['A','A'],['B','B'],['C','C']],t.grade||'')}</select></label><label>Trade notes<textarea name="notes" rows="4" placeholder="Record an observation about this EA execution.">${esc(t.notes)}</textarea></label><label class="checkbox-label"><input type="checkbox" name="reviewed" ${t.reviewed?'checked':''}> Mark this trade as reviewed</label><div class="form-footer">${button('Close','close','secondary')}<button class="btn primary" type="submit">Save review ${icon('check')}</button></div></form>`,'',true);}
function showDay(date){const trades=currentTrades({range:'all'}).filter(t=>t.date===date),m=metrics(trades),entry=userEntries().find(e=>e.date===date);modal(dateLabel(date),`<div class="day-detail-summary"><div><small>Net result</small><strong class="${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)}</strong></div><div><small>Trades</small><strong>${m.total}</strong></div><div><small>Win rate</small><strong>${m.winRate.toFixed(0)}%</strong></div></div>${tradeTable(trades)}<div class="day-reflection"><h3>Daily reflection</h3><p>${entry?esc(entry.content).replace(/\n/g,'<br>'):'A blank page is an opportunity. What did you learn today?'}</p>${isAdmin()?'':button(entry?'Edit reflection':'Write reflection','entry-date:'+date,'secondary','edit')}</div>`,'',true);}
function showEntry(id,date=anchorDate()){const entry=userEntries().find(e=>e.id===id);if(id&&!entry)return;modal(entry?'Edit your reflection':'A moment for reflection',`<form id="entry-form" data-id="${entry?.id||''}"><label>Date<input type="date" name="date" value="${entry?.date||date}" required></label><label>Give today a title<input name="title" value="${esc(entry?.title||'')}" placeholder="What’s your biggest takeaway?" required maxlength="120"></label><div class="form-grid"><label>How did you feel?<select name="mood">${selectOptions(['Focused','Calm','Confident','Impatient','Anxious'].map(x=>[x,x]),entry?.mood||'Focused')}</select></label><label>Process rating<select name="rating">${selectOptions([1,2,3,4,5].map(x=>[String(x),`${x} / 5 ${'★'.repeat(x)}`]),String(entry?.rating||4))}</select></label></div><label>Your reflection<textarea name="content" rows="7" placeholder="Did you follow your plan? What worked? What will you improve tomorrow?" required>${esc(entry?.content||'')}</textarea></label><div class="form-footer">${entry?button('Delete','delete-entry:'+entry.id,'danger text','trash'):button('Cancel','close','secondary')}<button type="submit" class="btn primary">Save reflection ${icon('check')}</button></div></form>`);}
function showUser(id){if(!hasAdminAccess())return;const u=db.users.find(u=>u.id===id);if(!u)return;const accounts=db.accounts.filter(a=>a.userId===id),trades=historyTrades().filter(t=>accounts.some(a=>a.id===t.accountId)),m=metrics(trades,accounts.some(a=>a.balanceKnown===false)?0:accounts.reduce((s,a)=>s+a.balance,0));modal('Trader profile',`<div class="user-profile-heading">${avatar(u.name,u.color)}<div><h2>${esc(u.name)}</h2><p>${esc(u.email)}</p>${badge(u.status)}</div></div><div class="day-detail-summary"><div><small>Net P&L · All time</small><strong class="${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)}</strong></div><div><small>Win rate</small><strong>${m.winRate.toFixed(1)}%</strong></div><div><small>Trades</small><strong>${m.total}</strong></div></div>${lineChart(m.curve)}<h3>Accounts & licenses</h3>${accounts.length?accounts.map(a=>`<button class="account-list-item" data-action="account:${a.id}">${icon('wallet')}<span><strong>${esc(a.name)}</strong><small>${esc(a.license)}</small></span>${badge(a.status)}${icon('chevron')}</button>`).join(''):empty('No licenses yet','Issue a license to give this user their first trading account.')}<div class="form-footer">${button(u.status==='Suspended'?'Restore access':'Suspend user','toggle-user:'+id,u.status==='Suspended'?'secondary':'danger text','shield')}${button('Open full panel','open-panel:'+id,'secondary','external')}${button('Issue license','issue-for:'+id,'primary','key')}</div>`,'',true);}
function showAddUser(){if(!isAdmin())return;modal('Add a trader',`<p class="muted">Add a trader and optionally issue their first account license.</p><form id="user-form"><label>Full name<input name="name" placeholder="Trader full name" required maxlength="70"></label><label>Email address<input name="email" type="email" placeholder="trader@example.com" required></label><label class="checkbox-label"><input type="checkbox" name="license" checked> Issue a license for their first trading account</label><p class="info-note">The trader signs in with this exact email. Access is linked on their first verified sign-in. No invitation email is sent.</p><div class="form-footer">${button('Cancel','close','secondary')}<button class="btn primary" type="submit">Create user ${icon('plus')}</button></div></form>`);}
function showIssue(userId=''){if(!hasAdminAccess())return;modal('Issue an account license',`<form id="license-form"><label>Assign to user<select name="userId" required>${selectOptions(db.users.filter(u=>u.status!=='Suspended').map(u=>[u.id,`${u.name} · ${u.email}`]),userId)}</select></label><label>Account name<input name="name" placeholder="e.g. Funded account" required maxlength="65"></label><div class="form-grid"><label>Account type<select name="type"><option>Live</option><option>Funded</option><option>Demo</option></select></label><label>License expiry<input type="date" name="expiry" value="${new Date(Date.now()+365*86400000).toISOString().slice(0,10)}" min="${today()}" required></label></div><label>Starting balance (USD)<input name="balance" type="number" min="0" value="0" required></label><div class="info-note">One license creates one journal account. The owner will bind their MT5 account when connecting.</div><div class="form-footer">${button('Cancel','close','secondary')}<button class="btn primary" type="submit">Generate license ${icon('key')}</button></div></form>`);}
function showActivate(){modal('Activate your assigned license',`<form id="activate-form"><p class="muted">Your administrator must assign this license to your account first.</p><label>License key<input name="license" placeholder="STRC-…" required maxlength="90"></label><label>Account nickname<input name="name" required maxlength="70"></label><div class="form-footer">${button('Cancel','close','secondary')}<button class="btn primary" type="submit">Activate license</button></div></form>`);}
function showAccount(id){const a=db.accounts.find(a=>a.id===id);if(!a||(!isAdmin()&&a.userId!==activeUserId()))return;modal('Account settings',`<form id="account-form" data-id="${id}"><label>Account name<input name="name" value="${esc(a.name)}" required maxlength="65"></label><div class="license-display"><span class="eyebrow">ACCOUNT LICENSE</span><code>${esc(a.license)}</code>${badge(a.status)}</div><div class="detail-grid"><div><small>MT5 account</small><strong>${esc(a.number||'Not bound')}</strong></div><div><small>Server</small><strong>${esc(a.server||'Not connected')}</strong></div><div><small>Owner</small><strong>${esc(db.users.find(u=>u.id===a.userId)?.name)}</strong></div><div><small>Expiry</small><strong>${a.expiry?dateLabel(a.expiry):'Not applicable'}</strong></div></div>${hasAdminAccess()&&a.license!=='File import'?`<label>License status<select name="status">${selectOptions(['Active','Suspended','Revoked'].map(x=>[x,x]),a.status)}</select></label><label>Expiry date<input type="date" name="expiry" value="${a.expiry}" required></label>`:''}<div class="form-footer">${a.connection==='Connected'?button('Disconnect','disconnect:'+a.id,'danger text','link'):button('Close','close','secondary')}<button type="submit" class="btn primary">Save changes ${icon('check')}</button></div></form>`);}
let wizard={};
function showConnect(id){const a=db.accounts.find(a=>a.id===id);if(!a||!canAccessAccount(id))return;modal('Connect your MT5 account',`<form id="connect-form" data-id="${esc(id)}"><div class="info-note">Read-only bridge. Your trading and investor passwords are never required.</div><label>MT5 account number<input name="number" value="${esc(a.number)}" required pattern="[0-9]{4,20}" ${a.number?'readonly':''}></label><div class="form-grid"><label>Broker<input name="broker" value="${esc(a.broker==='Not connected'?'':a.broker)}" required maxlength="70"></label><label>MT5 server<input name="server" value="${esc(a.server)}" required maxlength="100" ${a.number?'readonly':''}></label></div><div class="detail-grid"><div><small>Status</small><strong>${esc(a.connection)}</strong></div><div><small>Last heartbeat</small><strong>${esc(a.lastSync||'Awaiting connector')}</strong></div></div><p class="muted">Bind this license to one MT5 account, then generate a connector credential. Connected status appears after a real terminal heartbeat.</p><div class="form-footer">${a.number?button('Generate new credential','connector-key:'+id,'secondary','key'):''}<button class="btn primary" type="submit">${a.number?'Save binding':'Bind account'} ${icon('link')}</button></div></form>`);}
function showConnector(id,token){modal('Your connector credential',`<div class="info-note">Save this credential now. It is shown once; generating another revokes the previous one.</div><label>API endpoint<input readonly value="${esc(location.origin)}/api/ea/ingest"></label><label>Connector credential<input readonly value="${esc(token)}" autocomplete="off"></label><ol class="number-list"><li>Download StructureBridge.mq5 and compile it in MetaEditor.</li><li>In MT5 → Options → Expert Advisors, allow WebRequest for ${esc(location.origin)}.</li><li>Attach the bridge to one chart. Set JournalURL and ConnectorToken to the values above.</li><li>Keep MT5 or your VPS running. Structure updates after a real heartbeat.</li></ol><a class="btn primary" href="/assets/StructureBridge.mq5" download>Download MT5 bridge ${icon('download')}</a><p class="muted small-text">The bridge reads completed EA positions. Test it on a demo terminal before enabling it on your trading VPS.</p>`,button('I saved the credential','close','secondary'));}
function downloadCSV(name,rows){const csv=rows.map(r=>r.map(x=>{let v=String(x??'');if(/^[=+@\t\r]/.test(v)||/^-(?!\d)/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=name+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your CSV export is ready.');}
function exportTrades(){downloadCSV('structure-trades', [['Ticket','Account','Symbol','Type','Volume','Open Time','Open Price','Close Time','Close Price','Profit','Fees','R','Session','Expert Advisor','Magic number','Notes'],...currentTrades().map(t=>[t.ticket,db.accounts.find(a=>a.id===t.accountId)?.number||'',t.symbol,t.side,t.lots,t.openTime||(t.date+'T'+t.time+':00'),t.entry,t.closeTime||(t.date+'T'+t.time+':00'),t.exit,t.pnl,t.fees,t.r??'',t.session,t.eaName,t.magic??'',t.notes])]);}
function monthlyReport(){const m=currentMetrics();modal('Your performance report',`<div class="report-modal-brand"><img src="/assets/mark.svg" alt="Structure"><span>STRUCTURE / MONTHLY REVIEW</span></div><h3>${periodLabel()}</h3><p class="muted">${state.account==='all'?'All selected accounts':esc(db.accounts.find(a=>a.id===state.account)?.name)} · ${state.range} date filter</p><div class="day-detail-summary"><div><small>Net P&L</small><strong class="positive-text">${money(m.pnl,true)}</strong></div><div><small>Win rate</small><strong>${m.winRate.toFixed(1)}%</strong></div><div><small>Trades</small><strong>${m.total}</strong></div></div>${lineChart(m.curve)}<div class="detail-grid"><div><small>Profit factor</small><strong>${Number.isFinite(m.pf)?m.pf.toFixed(2):'∞'}</strong></div><div><small>Average return</small><strong>${rLabel(m)}</strong></div><div><small>Maximum drawdown</small><strong>${drawdownLabel(m)}</strong></div><div><small>Total fees</small><strong>${money(m.fees)}</strong></div></div>`,button('Download metrics CSV','summary-export','primary','download'),true);}
function confirmation(title,text,action,label='Confirm'){modal(title,`<p>${text}</p>`,button('Cancel','close','secondary')+button(label,action,'danger','check'));}
async function saveCloud(type,fields={},extra={}){const result=await operation(type,fields,extra);applyDB(result.db);return result;}
async function refreshCloud(){const result=await request('/api/workspace');applyDB(result.db);render();}
async function cloudAction(type,id){switch(type){
case'retry-boot':await bootstrap();return true;
case'signout':await request('/api/auth/logout',{method:'POST',body:'{}'});if(authProvider==='password'){session=null;close();bootError='';location.hash='/login';render();}else location.href='/signout-with-chatgpt?return_to=%2F';return true;
case'profile-menu':modal('Your workspace',`<div class="profile-photo">${avatar(session.name)}<div><strong>${esc(session.name)}</strong><small>${esc(session.email)}</small></div></div><div class="workspace-options">${button('My workspace','enter-user','secondary full','layers')}${hasAdminAccess()?button('Admin workspace','enter-admin','secondary full','shield'):''}${button('Sign out','signout','secondary full','logout')}</div><p class="info-note">Your ${esc(session.role)} permissions are verified on the server.</p>`);return true;
case'enter-user':case'enter-admin':close();navigate('overview',type==='enter-admin'&&hasAdminAccess()?'admin':'user');return true;
case'demo-info':modal('Your secure cloud journal',`<p>Trade history, reviews, users, and licenses are saved on the server. Administrators can connect their own Cloudflare KV namespace in Settings.</p>`,button('Done','close','primary'));return true;
case'notifications':modal('Workspace updates',activityList(db.activity.slice(0,8)),button('Done','close','primary'));return true;
case'confirm-delete-entry':await saveCloud('entry.delete',{}, {id});close();render();toast('Reflection deleted.');return true;
case'confirm-toggle-user':await saveCloud('users.status',{}, {id});close();render();toast('User access updated.');return true;
case'disconnect':confirmation('Disconnect this account?','This revokes its connector credential. History is retained.','confirm-disconnect:'+id,'Disconnect');return true;
case'confirm-disconnect':await saveCloud('account.disconnect',{}, {id});close();render();toast('Credential revoked. History retained.');return true;
case'connector-key':confirmation('Generate a connector credential?','The previous connector credential will stop working. Save the new credential and update your MT5 bridge.','confirm-connector-key:'+id,'Generate credential');return true;
case'confirm-connector-key':{const result=await saveCloud('account.rotate',{}, {id});render();showConnector(id,result.connectorToken);return true;}
case'refresh-connections':await refreshCloud();toast('Connection status refreshed from the server.');return true;
case'cloud-sync':{const result=await request('/api/cloudflare/sync',{method:'POST',body:'{}'});cloudStatus=result;render();toast(result.pending?'Some snapshots are pending. Retry shortly.':'Cloudflare snapshots are up to date.');return true;}
case'cloud-disconnect':confirmation('Disconnect Cloudflare KV?','Future snapshots stop. Your journal and existing snapshots are retained.','confirm-cloud-disconnect','Disconnect');return true;
case'confirm-cloud-disconnect':cloudStatus=await request('/api/cloudflare/disconnect',{method:'POST',body:'{}'});close();render();return true;
case'settings':if(id==='Cloudflare'){if(!hasAdminAccess())return true;cloudStatus=await request('/api/cloudflare');}return false;
case'toggle-user':if(!hasAdminAccess())return true;const u=db.users.find(u=>u.id===id);if(!u)return true;confirmation(u.status==='Suspended'?'Restore user access?':'Suspend this user?','The server checks this user’s status on every request, including EA sync.','confirm-toggle-user:'+id,u.status==='Suspended'?'Restore access':'Suspend user');return true;
case'connect-finish':case'reset-demo':case'confirm-reset-demo':case'import-demo':case'password-reset':return true;
}return false;}
async function handleAction(action,el){const [cloudType,...cloudParts]=action.split(':');if(await cloudAction(cloudType,cloudParts.join(':')))return;if(importUI.handles(action))return importUI.action(action,el);const [type,...rest]=action.split(':'),id=rest.join(':');switch(type){
case'close':close();break;
case'sidebar':state.sidebar=!state.sidebar;render();break;
case'collapse':state.collapsed=!state.collapsed;render();break;
case'theme':db.theme=db.theme==='dark'?'light':'dark';persist();render();break;
case'chart-equity':case'chart-drawdown':state.chartMode=type==='chart-equity'?'equity':'drawdown';render();break;
case'search':modal('Where would you like to go?',`<div class="search-input-large">${icon('search')}<input id="command-search" autofocus placeholder="Search pages, accounts, tools…" aria-label="Search workspace"></div><div id="command-results">${commandResults('')}</div>`);break;
case'goto':close();navigate(id);break;
case'reset-filters':Object.assign(state,{symbol:'all',session:'all',outcome:'all',query:'',tradePage:1});render();break;
case'trade':showTrade(id);break;
case'day':showDay(id);break;
case'calendar-prev':case'calendar-next':{const d=new Date(state.calendarYear,state.calendarMonth+(type==='calendar-next'?1:-1),1);state.calendarYear=d.getFullYear();state.calendarMonth=d.getMonth();render();break;}
case'calendar-today':{const date=anchorDate().split('-');state.calendarYear=Number(date[0]);state.calendarMonth=Number(date[1])-1;}render();break;
case'prev-trades':state.tradePage=Math.max(1,state.tradePage-1);render();break;
case'next-trades':state.tradePage++;render();break;
case'analytics':state.analyticsTab=id;render();break;
case'settings':state.settingsTab=id;render();break;
case'risk-settings':state.settingsTab='Risk management';navigate('settings');break;
case'new-entry':showEntry();break;
case'edit-entry':showEntry(id);break;
case'entry-date':showEntry(userEntries().find(e=>e.date===id)?.id,id);break;
case'delete-entry':confirmation('Delete this reflection?','This removes this reflection from your cloud journal.','confirm-delete-entry:'+id,'Delete reflection');break;
case'add-user':showAddUser();break;
case'user':openUserWorkspace(id);break;
case'user-profile':if(hasAdminAccess())showUser(id);break;
case'open-panel':openUserWorkspace(id);break;
case'back-to-admin':close();navigate('users','admin');break;
case'issue-license':showIssue();break;
case'issue-for':showIssue(id);break;
case'activate-license':showActivate();break;
case'account':showAccount(id);break;
case'connect':showConnect(id);break;
case'connect-back':showConnect(id,1,true);break;
case'connect-install':showConnect(id,2);break;
case'connect-verify':showConnect(id,3);break;
case'copy':try{await navigator.clipboard.writeText(id);toast('Copied to clipboard.');}catch{modal('Copy this value',`<input value="${esc(id)}" readonly onclick="this.select()" aria-label="Value to copy">`,button('Done','close','primary'));}break;
case'export':exportTrades();break;
case'summary-export':{const m=currentMetrics();downloadCSV('structure-performance',[['Metric','Value'],['Net P&L',m.pnl.toFixed(2)],['Trades',m.total],['Win rate',m.winRate.toFixed(2)],['Profit factor',Number.isFinite(m.pf)?m.pf.toFixed(2):'Infinity'],['Average R',m.rKnown?m.avgR.toFixed(2):'Not available'],['Max drawdown %',m.ddKnown?m.dd.toFixed(2):'Not available'],['Fees',m.fees.toFixed(2)]]);break;}
case'daily-export':downloadCSV('structure-daily',[['Date','Trades','Net P&L','Win rate'],...groupTrades(currentTrades(),'date').map(g=>[g.name,g.total,g.pnl.toFixed(2),g.winRate.toFixed(2)])]);break;
case'activity-export':if(isAdmin())downloadCSV('structure-activity',[['Time','Event','Type'],...db.activity.map(e=>[e.time,e.text,e.type])]);break;
case'monthly-report':monthlyReport();break;
case'help-connect':showConnect(visibleAccounts().find(a=>a.status==='Active')?.id);break;
}}
function commandResults(q){const nav=isAdmin()?adminNav:userNav;const items=nav.flatMap(x=>x[1]).filter(x=>x[2].toLowerCase().includes(q.toLowerCase()));return items.length?`<div class="command-list">${items.map(([id,ic,label])=>`<button data-action="goto:${id}">${icon(ic)}<span>${label}</span>${icon('arrow')}</button>`).join('')}</div>`:empty('No matching pages','Try “calendar”, “accounts”, or “analytics”.');}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){el.disabled=true;try{await handleAction(el.dataset.action,el);}catch(error){toast(error.message);}finally{el.disabled=false;}}else if(e.target.classList.contains('modal-backdrop'))close();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();state.sidebar=false;document.querySelector('.workspace')?.classList.remove('mobile-open');}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();handleAction('search');}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-action],#mt5-dropzone')){e.preventDefault();handleAction(e.target.dataset.action,e.target);}if(e.key==='Tab'&&overlay.firstChild){const els=[...overlay.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('change',e=>{if(importUI.change(e))return;if(e.target.id==='view-user-switch'){if(hasAdminAccess())location.hash=`/admin/users/${encodeURIComponent(e.target.value)}/${state.page}`;}else if(e.target.id==='account-filter'){state.account=e.target.value;state.tradePage=1;render();}else if(e.target.id==='range-filter'){state.range=e.target.value;state.tradePage=1;render();}else if(e.target.dataset.filter){state[e.target.dataset.filter]=e.target.value;state.tradePage=1;render();}});
let searchTimeout;document.addEventListener('input',e=>{if(importUI.input(e))return;if(e.target.id==='command-search'){document.querySelector('#command-results').innerHTML=commandResults(e.target.value);return;}const map={'trade-search':'query','journal-search':'journalQuery','admin-search':'adminQuery'},key=map[e.target.id];if(key){const id=e.target.id,value=e.target.value,start=e.target.selectionStart;state[key]=value;state.tradePage=1;clearTimeout(searchTimeout);searchTimeout=setTimeout(()=>{render();const input=document.getElementById(id);input?.focus();input?.setSelectionRange(start,start);},180);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(!form.checkValidity()){form.reportValidity();return;}const fields=Object.fromEntries(new FormData(form)),id=form.dataset.id;if(form.id==='import-confirm-form'){await importUI.submit(fields);return;}const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;
try{if(form.id==='password-login-form'){await request('/api/auth/login',{method:'POST',body:JSON.stringify(fields)});form.reset();location.hash='';await bootstrap();return;}if(form.id==='cloudflare-form'){cloudStatus=await request('/api/cloudflare/connect',{method:'POST',body:JSON.stringify(fields)});form.reset();render();toast('Cloudflare KV connected. Journal snapshots are syncing.');return;}
const types={'profile-form':'profile','risk-form':'risk','preferences-form':'preferences','trade-review-form':'review','entry-form':'entry.save','user-form':'users.create','license-form':'license.issue','activate-form':'license.activate','account-form':'account.update','connect-form':'account.bind'};const type=types[form.id];if(!type)return;const result=await saveCloud(type,fields,{id,ownerId:activeUserId()});close();render();if(type==='account.bind'){confirmation('Account bound','Generate a connector credential to configure the read-only MT5 bridge.','confirm-connector-key:'+id,'Generate credential');}else toast(result.message||'Changes saved to your cloud journal.');
}catch(error){if(form.id==='password-login-form'){bootError=error.message;render();}else toast(error.message);}finally{if(submit)submit.disabled=false;}});
window.addEventListener('hashchange',()=>{close();parseRoute();render();window.scrollTo({top:0,behavior:'instant'});});
document.addEventListener('dragover',e=>{if(e.target.closest?.('#mt5-dropzone'))e.preventDefault();});
document.addEventListener('drop',e=>{if(e.target.closest?.('#mt5-dropzone')){e.preventDefault();if(e.dataTransfer.files?.[0])importUI.read(e.dataTransfer.files[0]);}});
async function bootstrap(){app.innerHTML='<div class="cloud-loading" role="status"><img src="/assets/mark.svg" alt=""><h2>Opening your workspace<span class="gold-text">.</span></h2><p>Connecting to your secure cloud journal…</p></div>';try{try{db.theme=localStorage.getItem('structure-theme')||'light';}catch{}const response=await request('/api/session');session=response.user;authProvider=response.provider||'chatgpt';cloudStatus=response.cloudflare;const recent=await request('/api/workspace');applyDB(recent.db);if(!location.hash||['#/login','#/register','#/onboarding'].includes(location.hash))location.hash='/'+session.role+'/overview';bootError='';parseRoute();const current=anchorDate().split('-');state.calendarYear=+current[0];state.calendarMonth=+current[1]-1;const latest=db.importBatches[0];if(latest){state.range='all';const d=latest.dateEnd.split('-');state.calendarYear=+d[0];state.calendarMonth=+d[1]-1;}render();}catch(error){session=null;bootError=error.status===401?'':error.message;render();}}
await bootstrap();
